'use strict';

/**
* Replace double-precision complex floating-point strided array elements equal to `NaN` with a specified scalar constant.
*
* @module @stdlib/blas/ext/base/zfill-nan
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
* var zfillNaN = require( '@stdlib/blas/ext/base/zfill-nan' );
*
* var x = new Complex128Array( [ NaN, NaN, 3.0, 4.0, NaN, NaN, 7.0, 8.0 ] );
*
* var alpha = new Complex128( 5.0, 5.0 );
*
* zfillNaN( x.length, alpha, x, 1 );
* // x => <Complex128Array>[ 5.0, 5.0, 3.0, 4.0, 5.0, 5.0, 7.0, 8.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var zfillNaN;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	zfillNaN = main;
} else {
	zfillNaN = tmp;
}


// EXPORTS //

module.exports = zfillNaN;

// exports: { "ndarray": "zfillNaN.ndarray" }
